// Lead scoring — mirrors bots/cashpulse_revenue_bot.py::score_lead
const ROLE_WEIGHTS = { owner:25, ceo:25, founder:25, vp:20, director:18, head:18, manager:12, lead:10, analyst:5, intern:0, student:0 };
const SIGNAL_WEIGHTS = { explicit_budget:30, rfp_mentioned:20, competitor_named:15, timeline_under_30d:20, timeline_under_90d:10 };
const FREE = ['gmail.com','yahoo.com','hotmail.com','outlook.com'];
const out = [];
for (const item of items) {
  const j = item.json;
  let score = 0; const reasons = [];
  const role = (j.role || '').toLowerCase();
  let rolePts = 0; for (const k of Object.keys(ROLE_WEIGHTS)) if (role.includes(k)) rolePts = Math.max(rolePts, ROLE_WEIGHTS[k]);
  score += rolePts; if (rolePts) reasons.push(`role:${role}:+${rolePts}`);
  const size = j.company_size || 0;
  if (size >= 200) { score += 20; reasons.push('size:200+:+20'); }
  else if (size >= 50) { score += 12; reasons.push('size:50-199:+12'); }
  else if (size >= 10) { score += 6; reasons.push('size:10-49:+6'); }
  const domain = (j.email || '').split('@')[1] || '';
  if (domain && !FREE.includes(domain)) { score += 10; reasons.push('business_email:+10'); }
  else if (FREE.includes(domain)) { score -= 10; reasons.push('freemail:-10'); }
  for (const sig of (j.signals || [])) { const w = SIGNAL_WEIGHTS[sig] || 0; if (w) { score += w; reasons.push(`signal:${sig}:+${w}`); } }
  const deal = Number(j.deal_size_estimate || 0);
  if (deal >= 10000) { score += 15; reasons.push('deal>=10k:+15'); }
  else if (deal >= 2500) { score += 8; reasons.push('deal>=2.5k:+8'); }
  score = Math.max(0, Math.min(100, score));
  const tier = score >= 75 ? 'A' : score >= 50 ? 'B' : 'C';
  const requires_owner_alert = tier === 'A' && deal >= 10000;
  out.push({ json: { ...j, score, tier, reasons, requires_owner_alert } });
}
return out;
